  "titleCn": "泰国拟监管大型数字平台收费：Shopee自2022年上调GP费用10次涨幅433%、Lazada 7次367%、TikTok在查",
  "titleOrig": "Thailand to regulate large digital platform fees (Shopee GPF +433% over 10 hikes, Lazada +367% over 7, TikTok under review)",
  "summary": "泰国贸易竞争委员会拟要求具市场影响力的网约车、即时配送、外卖及电商平台在制定或调整佣金、服务费时公开信息并说明理由。监管草案10月19日获批，10月21日-11月20日征询公众意见，计划12月18日前生效。Shopee自2022年累计上调GP费用10次、涨幅433%，Lazada上调7次、涨幅367%，TikTok收费调整仍在调查中。对跨境卖家意味着平台费率透明度提升、成本结构待观察。",
